    test    rsi, rsi
    je      .done_enc
.loop_enc:
    movzx   ecx, byte ptr [rdi+rax]

    ; ROR cl, 3
    rol     cl, 5       ; ROL 5 is equivalent to ROR 3 for 8-bit values

    ; XOR with key
    mov     r8d, eax
    and     r8d, 7
    xor     cl, byte ptr [rdx+r8]

    mov     byte ptr [rdi+rax], cl
    inc     rax
    cmp     rax, rsi
    jne     .loop_enc
.done_enc:
    ret
```

